void setup() {
  Serial.begin(115200);
  Serial.println("Send a number (e.g., 123) or a letter (e.g., abc):");
}

void loop() {
  if (Serial.available() > 0) {
    char nextByte = Serial.peek(); 

    if (isDigit(nextByte)) {
      int incomingNumber = Serial.parseInt(); 
      Serial.print("Found a number: ");
      Serial.println(incomingNumber);
    } 
    else {
      char incomingChar = Serial.read(); 

      // Filter out newline and carriage return characters
      if (incomingChar != '\n' && incomingChar != '\r') {
        Serial.print("Found text: ");
        Serial.println(incomingChar);
      }
    }
  }
}
